/* US Navy set additions — cards appended after us-navy.js.
   (us-navy.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'us-navy.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('us-navy');
  if (!S) return;
  var extra = [{"name":"USS Argus","rarity":"uncommon","id":"uss-argus-1803","subtitle":"Sailing Brig","details":"Launched in 1803, Argus carried William Eaton's expedition to Egypt and backed the attack on Derna in 1805; HMS Pelican captured her in 1813.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thomas%20Whitcombe%20-%20Capture%20of%20the%20Argus%20August%2014th%201813.jpg?width=1024"},{"name":"USS Syren","rarity":"uncommon","id":"uss-syren-1803","subtitle":"Sailing Brig","details":"Launched in 1803, the brig Syren served in Commodore Preble's squadron at the bombardment of Tripoli in 1804 and cruised through the War of 1812.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/NH%2065536-KN.jpg?width=1024"},{"name":"USS Lawrence","rarity":"uncommon","id":"uss-lawrence-1813","subtitle":"Sailing Brig","details":"Perry's flagship at Lake Erie in 1813, Lawrence was shot to a wreck; Perry rowed to Niagara and won, reporting, 'We have met the enemy and they are ours.'","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Battle%20of%20Lake%20Erie%20--%20Commodore%20Perry%27s%20victory%20-%20Ballou%27s%20Pictorial%201856.jpg?width=800"},{"name":"USS Galena","rarity":"uncommon","id":"uss-galena-1862","subtitle":"Ironclad","details":"Launched in 1862, Galena was among the Union's first ironclads; her sloped armor was mauled at Drewry's Bluff, an early hard lesson in ironclad design.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Galena%20watercolor%20NH59541.jpg?width=1024"},{"name":"USS Cairo","rarity":"uncommon","id":"uss-cairo-1861","subtitle":"Ironclad Gunboat","details":"Launched in 1861, the City-class ironclad Cairo was the first warship sunk by a naval mine, a Confederate 'torpedo' in the Yazoo River in 1862.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/U.S.%20gunboat%20Cairo%20%28a.k.a.%20USS%20Cairo%29%20-%20Mississippi%20River%20Fleet%20-%20Original.tiff?width=1024"},{"name":"USS Carondelet","rarity":"uncommon","id":"uss-carondelet-1861","subtitle":"Ironclad Gunboat","details":"Launched in 1861, the ironclad gunboat Carondelet fought at Forts Henry and Donelson and daringly ran Island No. 10's batteries by night in 1862.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USSCarondelet.jpg?width=1024"},{"name":"USS Passaic","rarity":"uncommon","id":"uss-passaic-1862","subtitle":"Ironclad","details":"Launched in 1862, Passaic led an improved class of monitors and battered Charleston's defenses in 1863, armed with a huge 15-inch Dahlgren gun.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Passaic%20%281862%29.jpg?width=1024"},{"name":"USS Montauk","rarity":"uncommon","id":"uss-montauk-1862","subtitle":"Ironclad","details":"Launched in 1862, the monitor Montauk hammered Charleston's forts and destroyed the Confederate commerce raider Nashville on the Ogeechee River in 1863.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Uss%20Montauk%201862.jpg?width=1024"},{"name":"USS Weehawken","rarity":"uncommon","id":"uss-weehawken-1862","subtitle":"Ironclad","details":"Launched in 1862, the monitor Weehawken captured the Confederate ironclad Atlanta in June 1863, ending the fight with five shots in fifteen minutes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Weehawken%20CSS%20Atlanta.jpg?width=1024"},{"name":"USS Cowpens (CVL-25)","rarity":"common","id":"uss-cowpens-cvl-25","subtitle":"Light Aircraft Carrier","details":"Independence-class light carrier commissioned in 1943, nicknamed 'the Mighty Moo' for the Revolutionary War battle of Cowpens, South Carolina.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Cowpens_%28CVL-25%29_at_sea_on_31_August_1944.jpg?width=1024"},{"name":"USS Monterey (CVL-26)","rarity":"common","id":"uss-monterey-cvl-26","subtitle":"Light Aircraft Carrier","details":"Independence-class light carrier commissioned in 1943; future president Gerald Ford served aboard her and weathered the great typhoon of December 1944.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Monterey_%28CVL-26%29_in_Gulf_of_Mexico.jpg?width=1024"},{"name":"USS Langley (CVL-27)","rarity":"common","id":"uss-langley-cvl-27","subtitle":"Light Aircraft Carrier","details":"Independence-class light carrier commissioned in 1943 and named for aviation pioneer Samuel Langley; she later served France as the carrier La Fayette.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Langley_%28CVL-27%29_underway_off_Cape_Henry_on_6_October_1943_%2880-G-87113%29.jpg?width=1024"},{"name":"USS San Jacinto (CVL-30)","rarity":"common","id":"uss-san-jacinto-cvl-30","subtitle":"Light Aircraft Carrier","details":"Independence-class light carrier commissioned in 1943; future president George H. W. Bush flew torpedo-bomber missions from her as a young naval aviator.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_San_Jacinto_%28CVL-30%29_underway_at_sea_on_23_January_1944_%2880-G-212799%29.jpg?width=1024"},{"name":"USS Saipan (CVL-48)","rarity":"common","id":"uss-saipan-cvl-48","subtitle":"Light Aircraft Carrier","details":"Lead ship of the Saipan-class light carriers, commissioned in 1946; with too little war left to fight, she later became a major communications relay ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Saipan_%28CVL-48%29_underway_c1955.jpg?width=1024"},{"name":"USS Wright (CVL-49)","rarity":"common","id":"uss-wright-cvl-49","subtitle":"Light Aircraft Carrier","details":"Saipan-class light carrier commissioned in 1947 and named for the Wright brothers; she later served as a floating emergency command post, designated CC-2.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Wright_%28CVL-49%29_underway_in_the_early_1950s.jpg?width=1024"},{"name":"USS Long Island (CVE-1)","rarity":"common","id":"uss-long-island-cve-1","subtitle":"Escort Carrier","details":"The US Navy's first escort carrier, converted from a freighter and commissioned in 1941; her Marine fighters were among the first flown into Guadalcanal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Long_Island_%28CVE-1%29_in_San_Francisco_Bay%2C_California_%28USA%29%2C_on_10_June_1944_%2880-G-236393%29.jpg?width=1024"},{"name":"USS Block Island (CVE-21)","rarity":"common","id":"uss-block-island-cve-21","subtitle":"Escort Carrier","details":"Bogue-class escort carrier commissioned in 1943 that hunted U-boats in the Atlantic; sunk by U-549 in May 1944, the only US carrier lost in that ocean.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Block_Island_%28CVE-21%29_underway_Atlantic_Ocean_on_15_October_1943_%28NH_106576%29.jpg?width=1024"},{"name":"USS Casablanca (CVE-55)","rarity":"common","id":"uss-casablanca-cve-55","subtitle":"Escort Carrier","details":"Lead ship of the 50 Casablanca-class escort carriers, the most numerous carrier class ever built; commissioned in 1943 for convoy and support duty.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Casablanca_%28CVE-55%29_underway_at_sea_on_2_March_1945_%2880-G-320296%29.jpg?width=1024"},{"name":"USS Liscome Bay (CVE-56)","rarity":"common","id":"uss-liscome-bay-cve-56","subtitle":"Escort Carrier","details":"Casablanca-class escort carrier commissioned in August 1943; sunk by a Japanese submarine at Makin that November, among the lost was hero Dorie Miller.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Liscome_Bay_CVE56.jpg?width=1024"},{"name":"USS White Plains (CVE-66)","rarity":"common","id":"uss-white-plains-cve-66","subtitle":"Escort Carrier","details":"Casablanca-class escort carrier commissioned in 1943 whose lone 5-inch gun famously dueled Japanese battleships and cruisers off Samar in October 1944.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_White_Plains_%28CVE-66%29_at_San_Diego%2C_8_March_1944.jpg?width=1024"},{"name":"USS Gambier Bay (CVE-73)","rarity":"common","id":"uss-gambier-bay-cve-73","subtitle":"Escort Carrier","details":"Casablanca-class escort carrier commissioned in 1943, sunk by Japanese gunfire off Samar in October 1944; the only US carrier lost to surface gunfire.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CVE_73_Gambier_Bay.jpg?width=1024"},{"name":"USS Ranger (CV-61)","rarity":"common","id":"uss-ranger-cv-61","subtitle":"Aircraft Carrier","details":"Forrestal-class supercarrier commissioned in 1957, nicknamed 'Top Gun of the Pacific Fleet'; she served from the Vietnam War through Desert Storm.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_RANGER_august_1961_%286051633307%29.jpg?width=1024"},{"name":"USS Independence (CV-62)","rarity":"common","id":"uss-independence-cv-62","subtitle":"Aircraft Carrier","details":"Forrestal-class supercarrier commissioned in 1959; forward-deployed to Japan in her later years, she retired in 1998 after 39 years of service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Independence_%28CVA-62%29_underway_at_sea%2C_circa_in_1971_%28NH_97714-KN%29.jpg?width=1024"},{"name":"USS Dwight D. Eisenhower (CVN-69)","rarity":"common","id":"uss-dwight-d-eisenhower-cvn-69","subtitle":"Aircraft Carrier","details":"Nimitz-class nuclear carrier commissioned in 1977 and named for the 34th president; to her crew she is simply 'Ike', the general's own nickname.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_060617-N-0490C-010_The_Nimitz-class_aircraft_carrier_USS_Dwight_D._Eisenhower_%28CVN_69%29_conducts_a_turn_in_the_Atlantic_Ocean._Eisenhower_is_underway_conducting_routine_carrier_operations.jpg?width=1024"},{"name":"USS Carl Vinson (CVN-70)","rarity":"common","id":"uss-carl-vinson-cvn-70","subtitle":"Aircraft Carrier","details":"Nimitz-class nuclear carrier commissioned in 1982, named for the Georgia congressman who championed a strong US Navy across five decades in the House.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Carl_Vinson_%28CVN-70%29_underway_in_the_Pacific_Ocean_on_31_May_2015.JPG?width=1024"},{"name":"USS George Washington (CVN-73)","rarity":"common","id":"uss-george-washington-cvn-73","subtitle":"Aircraft Carrier","details":"Nimitz-class nuclear carrier commissioned on 4 July 1992 and named for the first president; she spent years forward-based in Yokosuka, Japan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20George%20Washington%20%28CVN-73%29%20underway%20in%20August%202015%20with%20CVW-5%20on%20deck.JPG?width=1024"},{"name":"USS John C. Stennis (CVN-74)","rarity":"common","id":"uss-john-c-stennis-cvn-74","subtitle":"Aircraft Carrier","details":"Nimitz-class nuclear carrier commissioned in 1995, named for Mississippi senator John C. Stennis, a towering longtime champion of naval aviation.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_110527-N-OI955-325_The_Nimitz-class_aircraft_carrier_USS_John_C._Stennis_%28CVN_74%29_is_underway_in_the_Pacific_Ocean.jpg?width=1024"},{"name":"USS Harry S. Truman (CVN-75)","rarity":"common","id":"uss-harry-s-truman-cvn-75","subtitle":"Aircraft Carrier","details":"Nimitz-class nuclear carrier commissioned in 1998, named for the 33rd president, whose wartime Senate committee had hunted waste and fraud.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Harry_S._Truman_%28CVN-75%29_underway_in_the_Atlantic_Ocean_on_11_September_2018_%28180911-N-EA818-2106%29.JPG?width=1024"},{"name":"USS Ronald Reagan (CVN-76)","rarity":"common","id":"uss-ronald-reagan-cvn-76","subtitle":"Aircraft Carrier","details":"Nimitz-class nuclear carrier commissioned in 2003, the first carrier named for a living former president; Nancy Reagan christened her in 2001.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USSRONALDREAGANgoodshot.jpg?width=1024"},{"name":"USS George H.W. Bush (CVN-77)","rarity":"common","id":"uss-george-hw-bush-cvn-77","subtitle":"Aircraft Carrier","details":"Tenth and final Nimitz-class carrier, commissioned in 2009 and named for the 41st president, himself a World War II naval aviator shot down in 1944.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_110129-N-3885H-158_USS_George_H.W._Bush_%28CVN_77%29_is_underway_in_the_Atlantic_Ocean.jpg?width=1024"},{"name":"USS Princeton (CV-37)","rarity":"common","id":"uss-princeton-cv-37","subtitle":"Aircraft Carrier","details":"Essex-class carrier commissioned in November 1945 and named to honor the light carrier lost at Leyte Gulf; she went on to serve in Korea and Vietnam.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Princeton_%28LPH-5%29_underway_at_sea%2C_circa_1965_%28NNAM.1996.488.060.030%29.jpg?width=1024"},{"name":"USS Kentucky (BB-6)","rarity":"common","id":"uss-kentucky-bb-6","subtitle":"Battleship","details":"Kearsarge-class battleship commissioned in 1900; she cruised to East Asia and later served as a training ship in the First World War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_KENTUCKY_LCCN2014704670_%28cropped%29.tif?width=1024"},{"name":"USS Alabama (BB-8)","rarity":"common","id":"uss-alabama-bb-8","subtitle":"Battleship","details":"Illinois-class battleship commissioned in 1900; she cruised around the world with the Great White Fleet and served as a training ship in World War I.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Alabama_%28BB-8%29_1912.jpg?width=1024"},{"name":"USS Wisconsin (BB-9)","rarity":"common","id":"uss-wisconsin-bb-9","subtitle":"Battleship","details":"Illinois-class battleship commissioned in 1901; she served on the Asiatic Station and sailed with the Great White Fleet around the world in 1907-09.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Uss_wisconsin_bb-9.jpg?width=1024"},{"name":"USS Missouri (BB-11)","rarity":"common","id":"uss-missouri-bb-11","subtitle":"Battleship","details":"Maine-class battleship commissioned in 1903; she cruised with the Great White Fleet and served as a training ship during the First World War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Missouri_in_1912.tiff?width=1024"},{"name":"USS Ohio (BB-12)","rarity":"common","id":"uss-ohio-bb-12","subtitle":"Battleship","details":"Maine-class battleship commissioned in 1904; flagship of the Asiatic Fleet, she completed the Great White Fleet's world cruise in 1907-09.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Uss_ohio_bb-12.jpg?width=1024"},{"name":"USS Virginia (BB-13)","rarity":"common","id":"uss-virginia-bb-13","subtitle":"Battleship","details":"Lead ship of her class, commissioned in 1906; she sailed from Hampton Roads with the Great White Fleet on its world cruise in December 1907.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Virginia_LOC_npcc_32728.jpg?width=1024"},{"name":"USS Nebraska (BB-14)","rarity":"common","id":"uss-nebraska-bb-14","subtitle":"Battleship","details":"Virginia-class battleship commissioned in 1907; she sailed with the Great White Fleet and escorted convoys in the First World War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Nebraska_in_1910.tiff?width=1024"},{"name":"USS New Jersey (BB-16)","rarity":"common","id":"uss-new-jersey-bb-16","subtitle":"Battleship","details":"Virginia-class battleship commissioned in 1906; she cruised with the Great White Fleet and was sunk in bombing trials off Cape Hatteras in 1923.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_New_Jersey_%28BB-16%29_in_camouflage_coat%2C_1918_edit.jpg?width=1024"},{"name":"USS Rhode Island (BB-17)","rarity":"common","id":"uss-rhode-island-bb-17","subtitle":"Battleship","details":"Virginia-class battleship commissioned in 1906; she sailed with the Great White Fleet and served on convoy escort duty in the First World War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Rhode_Island_BB-17.jpg?width=1024"},{"name":"USS Connecticut (BB-18)","rarity":"common","id":"uss-connecticut-bb-18","subtitle":"Battleship","details":"Lead ship of her class, commissioned in 1906; flagship of the Atlantic Fleet and of the Great White Fleet on its 1907-09 world cruise.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Connecticut_BB-18_underway.jpg?width=1024"},{"name":"USS Louisiana (BB-19)","rarity":"common","id":"uss-louisiana-bb-19","subtitle":"Battleship","details":"Connecticut-class battleship commissioned in 1906; she carried President Roosevelt to Panama in the first overseas trip by a sitting US president.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Uss_louisiana_bb_19.jpg?width=1024"},{"name":"USS Vermont (BB-20)","rarity":"common","id":"uss-vermont-bb-20","subtitle":"Battleship","details":"Connecticut-class battleship commissioned in 1908; she joined the Great White Fleet's world cruise at San Francisco for its second leg.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Uss_vermont_bb_20.jpg?width=1024"},{"name":"USS Kansas (BB-21)","rarity":"common","id":"uss-kansas-bb-21","subtitle":"Battleship","details":"Connecticut-class battleship commissioned in 1907; she completed the full Great White Fleet world cruise of 1907-09 with the Atlantic Fleet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Kansas_%28BB-21%29.jpg?width=1024"},{"name":"USS Minnesota (BB-22)","rarity":"common","id":"uss-minnesota-bb-22","subtitle":"Battleship","details":"Connecticut-class battleship commissioned in 1907; she struck a German mine off Fire Island in 1918 but reached port under her own power.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Minnesota_%28BB-22%29.jpg?width=1024"},{"name":"USS Mississippi (BB-23)","rarity":"common","id":"uss-mississippi-bb-23","subtitle":"Battleship","details":"Lead ship of the last US pre-dreadnought class, commissioned in 1908; sold to Greece in 1914, she served the Greek Navy as the battleship Kilkis.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Mississippi%20BB-23.jpg?width=1024"},{"name":"USS New Hampshire (BB-25)","rarity":"common","id":"uss-new-hampshire-bb-25","subtitle":"Battleship","details":"Connecticut-class battleship commissioned in 1908; the last US pre-dreadnought completed, she served on convoy duty in the First World War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_New_Hampshire_1910.tiff?width=1024"},{"name":"USS Columbia (CL-56)","rarity":"common","id":"uss-columbia-cl-56","subtitle":"Light Cruiser","details":"Cleveland-class light cruiser commissioned in 1942. She supported landings from the Solomons to Lingayen Gulf and survived kamikaze hits in 1945.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Columbia_%28CL-56%29_off_San_Pedro_1945.jpg?width=1024"},{"name":"USS Montpelier (CL-57)","rarity":"common","id":"uss-montpelier-cl-57","subtitle":"Light Cruiser","details":"Cleveland-class light cruiser commissioned in 1942 as flagship of Cruiser Division 12. She fought through the Solomons and Philippines campaigns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Montpelier_%28CL-57%29_in_Dec_1942.jpg?width=1024"},{"name":"USS Denver (CL-58)","rarity":"common","id":"uss-denver-cl-58","subtitle":"Light Cruiser","details":"Cleveland-class light cruiser commissioned in October 1942. She fought in the night action at Empress Augusta Bay and across the southwest Pacific.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Denver_%28CL-58%29_underway%2C_circa_in_December_1942_%2819-N-39431%29.jpg?width=1024"},{"name":"USS Birmingham (CL-62)","rarity":"common","id":"uss-birmingham-cl-62","subtitle":"Light Cruiser","details":"Cleveland-class light cruiser commissioned in 1943. She suffered heavy casualties when the carrier Princeton exploded beside her in October 1944.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Birmingham_%28CL-62%29_off_the_Mare_Island_Naval_Shipyard_on_7_February_1944.jpg?width=1024"},{"name":"USS Mobile (CL-63)","rarity":"common","id":"uss-mobile-cl-63","subtitle":"Light Cruiser","details":"Cleveland-class light cruiser commissioned in 1943. She fought from the Gilberts and Marshalls to Okinawa, screening the fast carrier task forces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Mobile_%28CL-63%29_underway_in_the_Pacific_Ocean%2C_in_October_1943_%28NH_98166%29.jpg?width=1024"},{"name":"USS Oakland (CL-95)","rarity":"common","id":"uss-oakland-cl-95","subtitle":"Light Cruiser","details":"Atlanta-class antiaircraft light cruiser commissioned in 1943. She screened the fast carriers and bombarded shore targets at Okinawa in 1945.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Oakland_%28CL-95%29_in_San_Francisco_Bay_on_2_August_1943_%28NH_98442%29.jpg?width=1024"},{"name":"USS Worcester (CL-144)","rarity":"common","id":"uss-worcester-cl-144","subtitle":"Light Cruiser","details":"Lead Worcester-class light cruiser, commissioned in 1948 with rapid-fire dual-purpose 6-inch guns. She deployed to Korea with the Seventh Fleet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Worcester_%28CL-144%29_underway_in_November_1949.jpg?width=1024"},{"name":"USS Roanoke (CL-145)","rarity":"common","id":"uss-roanoke-cl-145","subtitle":"Light Cruiser","details":"Worcester-class light cruiser commissioned in 1949, among the last US gun cruisers built. She served chiefly in the Atlantic and Mediterranean.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Roanoke_%28CL-145%29_underway_at_slow_speed%2C_circa_the_early_1950s_%28NH_106501%29.jpg?width=1024"},{"name":"USS Columbus (CA-74)","rarity":"common","id":"uss-columbus-ca-74","subtitle":"Heavy Cruiser","details":"Baltimore-class heavy cruiser commissioned in 1945. She was rebuilt with Talos and Tartar missiles and recommissioned as CG-12 in 1962.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Columbus_%28CA-74%29_off_the_coast_of_Spain%2C_12_July_1948_%28NH_98457%29.jpg?width=1024"},{"name":"USS Chicago (CG-11)","rarity":"common","id":"uss-chicago-cg-11","subtitle":"Guided Missile Cruiser","details":"Commissioned in 1945 as heavy cruiser CA-136. She was rebuilt with Talos and Tartar missile batteries and recommissioned as CG-11 in 1964.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Chicago%20%28CG-11%29%20underway%20in%20the%20Coral%20Sea%2C%20in%20October%201979.jpg?width=1024"},{"name":"USS Albany (CG-10)","rarity":"common","id":"uss-albany-cg-10","subtitle":"Guided Missile Cruiser","details":"Commissioned in 1946 as heavy cruiser CA-123. Stripped of guns and rebuilt around Talos missiles, she recommissioned as CG-10 in 1962.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Albany%20%28CG-10%29%20underway%20c1963.jpg?width=1024"},{"name":"USS Leahy (CG-16)","rarity":"common","id":"uss-leahy-cg-16","subtitle":"Guided Missile Cruiser","details":"Lead Leahy-class guided-missile cruiser, commissioned in 1962 as DLG-16. Her Terrier missile batteries guarded carrier groups through the Cold War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Leahy_%28CG-16%29_at_sea_off_San_Diego%2C_in_May_1978.jpg?width=1024"},{"name":"USS Truxtun (CGN-35)","rarity":"common","id":"uss-truxtun-cgn-35","subtitle":"Guided Missile Cruiser","details":"Nuclear-powered guided-missile cruiser commissioned in 1967 as DLGN-35. She made repeated Vietnam deployments screening carriers in the Tonkin Gulf.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Truxtun_%28CGN-35%29_underway_in_the_Pacific_Ocean_on_3_January_1989_%286450110%29.jpg?width=1024"},{"name":"USS Virginia (CGN-38)","rarity":"common","id":"uss-virginia-cgn-38","subtitle":"Guided Missile Cruiser","details":"Lead Virginia-class nuclear guided-missile cruiser, commissioned in 1976. She fired Tomahawk missiles in combat during the 1991 Gulf War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Virginia_%28CGN-38%29_underway_during_the_NATO_Exercise_Distant_Drum%2C_18_May_1983_%28330-CFD-DN-SC-87-02014%29.jpg?width=1024"},{"name":"USS Ticonderoga (CG-47)","rarity":"common","id":"uss-ticonderoga-cg-47","subtitle":"Guided Missile Cruiser","details":"Lead ship of the Aegis cruisers, commissioned in 1983. Her SPY-1 phased-array radar reshaped air defense for the US carrier battle group.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_port_bow_view_of_USS_Ticonderoga_%28CG-47%29_underway_during_sea_trials_May_1982_DN-SC-84-00167.jpg?width=1024"},{"name":"USS Bunker Hill (CG-52)","rarity":"common","id":"uss-bunker-hill-cg-52","subtitle":"Guided Missile Cruiser","details":"Ticonderoga-class Aegis cruiser commissioned in 1986, the first of her class fitted with vertical missile launchers for Tomahawk strikes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_110917-N-BC134-315_The_guided-missile_cruiser_USS_Bunker_Hill_%28CG_52%29_transits_the_Pacific_Ocean._Bunker_Hill_is_conducting_a_three-week_co.jpg?width=1024"},{"name":"USS Lake Erie (CG-70)","rarity":"common","id":"uss-lake-erie-cg-70","subtitle":"Guided Missile Cruiser","details":"Ticonderoga-class Aegis cruiser commissioned in 1993. In 2008 she destroyed a failing spy satellite with a modified SM-3 missile above the Pacific.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_080626-N-6674H-048_The_guided-missile_cruiser_USS_Lake_Erie_%28CG_70%29_arrives_at_Naval_Station_Pearl_Harbor_for_Rim_of_the_Pacific_%28RIMPAC%29_2008.jpg?width=1024"},{"name":"USS Cowpens (CG-63)","rarity":"common","id":"uss-cowpens-cg-63","subtitle":"Guided Missile Cruiser","details":"Ticonderoga-class Aegis cruiser commissioned in 1991, named for the Revolutionary War battle. She deployed repeatedly to the Pacific and Persian Gulf.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Cowpens_underway_in_the_South_China_Sea._%2810476775924%29.jpg?width=1024"},{"name":"USS Gettysburg (CG-64)","rarity":"common","id":"uss-gettysburg-cg-64","subtitle":"Guided Missile Cruiser","details":"Ticonderoga-class Aegis cruiser commissioned in 1991 and named for the 1863 battle. She screened carrier groups in the Atlantic and Middle East.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Gettsyburg_%28CG-64%29.jpg?width=1024"},{"name":"USS Sampson (DD-63)","rarity":"common","id":"uss-sampson-dd-63","subtitle":"Destroyer","details":"Sampson-class destroyer commissioned in 1916; based at Queenstown, Ireland, she escorted convoys through U-boat waters in the First World War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Sampson_DD-63.jpg?width=1024"},{"name":"USS Rowe (DD-564)","rarity":"common","id":"uss-rowe-dd-564","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1944; she screened the fast carriers and supported the Philippines and Okinawa campaigns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Rowe_%28DD-564%29_underway_at_sea%2C_in_the_1950s.jpg?width=1024"},{"name":"USS Brownson (DD-518)","rarity":"common","id":"uss-brownson-dd-518","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; she was lost to Japanese dive bombers off Cape Gloucester in December 1943, the first Fletcher sunk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Brownson_%28DD-518%29_underway_at_sea%2C_circa_in_early_1943_%28NH_107241%29.jpg?width=1024"},{"name":"USS Gansevoort (DD-608)","rarity":"common","id":"uss-gansevoort-dd-608","subtitle":"Destroyer","details":"Benson-class destroyer commissioned in 1942; she supported landings from the Aleutians to the Philippines across the wartime Pacific.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Gansevoort_%28DD-608%29_off_the_Mare_Island_Naval_Shipyard%2C_California_%28USA%29%2C_17_August_1945_%286017-45%29.jpg?width=1024"},{"name":"USS Meade (DD-602)","rarity":"common","id":"uss-meade-dd-602","subtitle":"Destroyer","details":"Benson-class destroyer commissioned in 1942; she fought through the Solomons, Gilberts and Marshalls and screened Pacific landing forces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Meade_%28DD-602%29_off_New_York_City_on_20_June_1942_%2819-N-30842%29.jpg?width=1024"},{"name":"USS Parker (DD-604)","rarity":"common","id":"uss-parker-dd-604","subtitle":"Destroyer","details":"Benson-class destroyer commissioned in 1942; she supported the Sicily and Salerno landings in Europe before finishing the war in the Pacific.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Parker_%28DD-604%29_at_sea%2C_circa_1942.jpg?width=1024"},{"name":"USS La Vallette (DD-448)","rarity":"common","id":"uss-la-vallette-dd-448","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; she fought at Guadalcanal and across the Pacific and was mined at Mariveles in February 1945.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_La_Vallette_%28DD-448%29_underway%2C_circa_in_late_1942.jpg?width=1024"},{"name":"USS Jenkins (DD-447)","rarity":"common","id":"uss-jenkins-dd-447","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; she fought at Kolombangara and through the Solomons, then served again off Korea and Vietnam.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Jenkins_%28DD-447%29_off_the_Mare_Island_Naval_Shipyard_on_15_January_1944.jpg?width=1024"},{"name":"USS Taylor (DD-468)","rarity":"common","id":"uss-taylor-dd-468","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; a Destroyer Squadron 21 veteran of the Solomons, she served in three wars before 1969.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Taylor_%28DD-468%29_in_San_Francisco_Bay%2C_California_%28USA%29%2C_on_26_January_1944_%2880-G-1038542%29.jpg?width=1024"},{"name":"USS Sproston (DD-577)","rarity":"common","id":"uss-sproston-dd-577","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; she screened carriers and supported landings from the Marshalls to Okinawa in the Pacific war.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Sproston_%28DDE-577%29_underway_in_1958.jpg?width=1024"},{"name":"USS Wickes (DD-578)","rarity":"common","id":"uss-wickes-dd-578","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; she escorted carriers and convoys and supported the Philippines and Okinawa campaigns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Wickes_%28DD-578%29_at_Hollandia_in_1944.JPG?width=1024"},{"name":"USS Philip (DD-498)","rarity":"common","id":"uss-philip-dd-498","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; she fought at Vella Gulf and through the Solomons campaign with Destroyer Squadron 21.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Philip_%28DD-498%29_underway_in_the_Pacific_Ocean_on_9_July_1968_%28NH_98592%29.jpg?width=1024"},{"name":"USS Renshaw (DD-499)","rarity":"common","id":"uss-renshaw-dd-499","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; she fought through the Solomons and Philippines and survived a torpedo hit in February 1945.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Renshaw_%28DDE-499%29_operating_off_Korea_on_27_July_1951_%2880-G-432955%29.jpg?width=1024"},{"name":"USS Ringgold (DD-500)","rarity":"common","id":"uss-ringgold-dd-500","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; she bombarded Makin atoll and supported landings from the Gilberts through the Philippines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Ringgold_%28DD-500%29_underway_in_the_Atlantic_Ocean%2C_circa_in_May_1943_%2819-N-44875%29.jpg?width=1024"},{"name":"USS Schroeder (DD-501)","rarity":"common","id":"uss-schroeder-dd-501","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; she screened the fast carriers through the Marshalls, Marianas and Philippines campaigns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Schroeder_%28DD-501%29_underway_in_the_Pacific_Ocean_on_9_October_1945.jpg?width=1024"},{"name":"USS Sigsbee (DD-502)","rarity":"common","id":"uss-sigsbee-dd-502","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; a kamikaze tore off her stern at Okinawa in April 1945, yet she stayed afloat and was repaired.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Sigsbee_%28DD-502%29_underway_in_the_Pacific_Ocean_on_23_June_1944_%2880-G-321648%29.jpg?width=1024"},{"name":"USS Conway (DD-507)","rarity":"common","id":"uss-conway-dd-507","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; she fought in the Solomons and supported landings across the Pacific into the Philippines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Conway_%28DDE-507%29_underway_on_6_December_1950_%2824746297%29.jpg?width=1024"},{"name":"USS Cony (DD-508)","rarity":"common","id":"uss-cony-dd-508","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; she fought at Kolombangara and screened carriers and landing forces across the Pacific.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Cony_%28DDE-508%29_in_Hampton_Roads_on_12_March_1957_%28NH_104882%29.jpg?width=1024"},{"name":"USS Eaton (DD-510)","rarity":"common","id":"uss-eaton-dd-510","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; she served in the wartime Pacific and survived a 1956 collision with battleship Wisconsin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Eaton_%28DD-510%29_underway_at_sea_in_September_1964_%28NH_107258%29.jpg?width=1024"},{"name":"USS Bache (DD-470)","rarity":"common","id":"uss-bache-dd-470","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; she fought at Surigao Strait and supported landings from the Solomons to the Philippines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Bache_%28DD-470%29_underway_at_sea%2C_in_the_1960s.jpg?width=1024"},{"name":"USS Beale (DD-471)","rarity":"common","id":"uss-beale-dd-471","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; she fought through the Solomons and at Surigao Strait during the Battle of Leyte Gulf.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Beale_%28DD-471%29_underway_on_27_October_1964_%28NH_103711%29.jpg?width=1024"},{"name":"USS Guest (DD-472)","rarity":"common","id":"uss-guest-dd-472","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; she supported landings and screened carriers from the Gilberts through the Philippines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Guest_%28DD-472%29_underway_in_June_1943.jpg?width=1024"},{"name":"USS Bennett (DD-473)","rarity":"common","id":"uss-bennett-dd-473","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; she supported Pacific landings and was struck by a kamikaze off Okinawa in April 1945.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Bennett_%28DD-473%29_off_Boston%2C_Massacusetts_%28USA%29%2C_on_7_May_1943.jpg?width=1024"},{"name":"USS Fullam (DD-474)","rarity":"common","id":"uss-fullam-dd-474","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; she screened carriers and bombarded shore targets from the Marshalls through Okinawa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Fullam_%28DD-474%29_off_the_Mare_Island_Naval_Shipyard_on_25_July_1943_%2819-N-49046%29.jpg?width=1024"},{"name":"USS Hudson (DD-475)","rarity":"common","id":"uss-hudson-dd-475","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; she supported the Bougainville and Philippines landings and rescued downed aircrews at sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Hudson_%28DD-475%29_rescueing_a_downed_aircrew_off_Guam_on_21_July_1944_%2880-G-248291%29.jpg?width=1024"},{"name":"USS Hutchins (DD-476)","rarity":"common","id":"uss-hutchins-dd-476","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; she fought through the Solomons and supported Allied landings across the Pacific to Okinawa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Hutchins_%28DD-476%29_underway_at_sea_on_24_February_1945_%2880-G-310958%29.jpg?width=1024"},{"name":"USS Pringle (DD-477)","rarity":"common","id":"uss-pringle-dd-477","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1942; she fought from the Solomons to Okinawa, where a kamikaze sank her on 16 April 1945.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Pringle_%28DD-477%29_underway_in_December_1942.jpg?width=1024"},{"name":"USS Braine (DD-630)","rarity":"common","id":"uss-braine-dd-630","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; she supported Pacific landings and survived kamikaze hits off Okinawa in May 1945.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Braine_%28DD-630%29_underway_in_the_Pacific_Ocean%2C_in_1944.jpg?width=1024"},{"name":"USS Erben (DD-631)","rarity":"common","id":"uss-erben-dd-631","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; she screened carriers in the Pacific war and returned to combat duty off Korea in the 1950s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Erben_%28DD-631%29_underway_the_1950s.jpg?width=1024"},{"name":"USS Hale (DD-642)","rarity":"common","id":"uss-hale-dd-642","subtitle":"Destroyer","details":"Fletcher-class destroyer commissioned in 1943; she supported landings from the Marshalls to the Philippines and screened carrier forces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Hale_%28DD-642%29_steaming_out_of_San_Diego%2C_circa_in_March_1951_%28NH_107205%29.jpg?width=1024"},{"name":"USS Knox (FF-1052)","rarity":"common","id":"uss-knox-ff-1052","subtitle":"Frigate","details":"Lead ship of the Knox-class frigates, commissioned in 1969; these Cold War escorts hunted submarines and screened carriers and convoys.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Knox_%28FF-1052%29_underway_at_sea_on_9_December_1981_%286349375%29.jpeg?width=1024"},{"name":"USS Constellation (FFG-62)","rarity":"common","id":"uss-constellation-ffg-62","subtitle":"Guided Missile Frigate","details":"Lead ship of the Constellation-class guided missile frigates, named in 2020 to honor the frigates of the early United States Navy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Artist_rendering_of_USS_Constellation_%28FFG-62%29.jpg?width=1024"},{"name":"USS Gato (SS-212)","rarity":"common","id":"uss-gato-ss-212","subtitle":"Submarine","details":"Lead ship of the famous Gato class, commissioned on the last day of 1941, Gato carried the Pacific war to Japan across eleven war patrols at sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Gato%3B0821201.jpg?width=1024"},{"name":"USS Greenling (SS-213)","rarity":"common","id":"uss-greenling-ss-213","subtitle":"Submarine","details":"Commissioned in 1942, Gato-class Greenling made twelve war patrols, raiding Japanese shipping lanes from Truk to the coast of Honshu itself.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Greenling%3B0821305.jpg?width=1024"},{"name":"USS Grouper (SS-214)","rarity":"common","id":"uss-grouper-ss-214","subtitle":"Submarine","details":"Commissioned in 1942, Gato-class Grouper made twelve war patrols and later served for years as a hunter-killer and auxiliary research submarine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Grouper%3B0821405.jpg?width=1024"},{"name":"USS Haddock (SS-231)","rarity":"common","id":"uss-haddock-ss-231","subtitle":"Submarine","details":"Commissioned in 1942, Gato-class Haddock made thirteen war patrols and earned eleven battle stars hunting Japanese shipping across the Pacific.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Haddock%3B0823105.jpg?width=1024"},{"name":"USS Halibut (SS-232)","rarity":"common","id":"uss-halibut-ss-232","subtitle":"Submarine","details":"Commissioned in 1943, Gato-class Halibut made ten patrols before aircraft bombs so damaged her in November 1944 that she never patrolled again.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Halibut%3B0823206.jpg?width=1024"},{"name":"USS Herring (SS-233)","rarity":"common","id":"uss-herring-ss-233","subtitle":"Submarine","details":"Commissioned in 1944, Herring was the only U.S. submarine sunk by shore batteries, lost to Japanese guns in the Kuril Islands in June 1944.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Herring_%28SS-233%29.jpg?width=1024"},{"name":"USS Kingfish (SS-234)","rarity":"common","id":"uss-kingfish-ss-234","subtitle":"Submarine","details":"Commissioned in 1942, Gato-class Kingfish made eleven war patrols and in 1945 rescued British airmen adrift in the South China Sea after a raid.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Kingfish%3B0823406.jpg?width=1024"},{"name":"USS Shad (SS-235)","rarity":"common","id":"uss-shad-ss-235","subtitle":"Submarine","details":"Commissioned in 1942, Gato-class Shad began her career in European waters, torpedoing an Italian destroyer escort off Spain on an early patrol.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Shad%3B0823504.jpg?width=1024"},{"name":"USS Guardfish (SS-217)","rarity":"common","id":"uss-guardfish-ss-217","subtitle":"Submarine","details":"Commissioned in 1942, Gato-class Guardfish sank a Japanese destroyer on her first patrol and ranked among the Pacific fleet's busiest hunters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Guardfish%3B0821701.jpg?width=1024"},{"name":"USS Albacore (SS-218)","rarity":"common","id":"uss-albacore-ss-218","subtitle":"Submarine","details":"Commissioned in 1942, Gato-class Albacore sank the carrier Taiho at the Philippine Sea before being lost with all hands off Hokkaido in 1944.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Albacore-ii.jpg?width=1024"},{"name":"USS Thresher (SS-200)","rarity":"common","id":"uss-thresher-ss-200","subtitle":"Submarine","details":"Tambor-class Thresher, commissioned in 1940, made fifteen war patrols, the most of any U.S. submarine to survive the Pacific war's hardest years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Thresher_%28SS-200%29.jpg?width=1024"},{"name":"USS Gar (SS-206)","rarity":"common","id":"uss-gar-ss-206","subtitle":"Submarine","details":"Commissioned in 1941, Tambor-class Gar patrolled from Pearl Harbor and Australia, later training new submarine crews in the war's final year.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ss206Gar.jpg?width=1024"},{"name":"USS Grampus (SS-207)","rarity":"common","id":"uss-grampus-ss-207","subtitle":"Submarine","details":"Commissioned in 1941, Tambor-class Grampus was lost with all 71 aboard in the Solomon Islands in early 1943, on her sixth war patrol at sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Grampus_%28SS-207%29_-_19-N-23818.jpg?width=1024"},{"name":"USS Grayback (SS-208)","rarity":"common","id":"uss-grayback-ss-208","subtitle":"Submarine","details":"Commissioned in 1941, Tambor-class Grayback ranked among the top U.S. submarines in tonnage before aircraft sank her in February 1944; found in 2019.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grayback_%28SS208%29._Port_side%2C_05-06-1941_-_NARA_-_513040.tif?width=1024"},{"name":"USS Grenadier (SS-210)","rarity":"common","id":"uss-grenadier-ss-210","subtitle":"Submarine","details":"Commissioned in 1941, Tambor-class Grenadier was scuttled after air attack near Penang in April 1943; her crew survived as prisoners of war.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Grenadier_%28SS-210%29.tif?width=1024"},{"name":"USS Gudgeon (SS-211)","rarity":"common","id":"uss-gudgeon-ss-211","subtitle":"Submarine","details":"Commissioned in 1941, Gudgeon made the first U.S. submarine sinking of the war, an enemy submarine in January 1942, and was lost in April 1944.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/R_%285%29.jpg?width=1024"},{"name":"USS Darter (SS-227)","rarity":"common","id":"uss-darter-ss-227","subtitle":"Submarine","details":"Commissioned in 1943, Darter and Dace sank two Japanese heavy cruisers before Leyte; Darter then grounded and was abandoned, her crew all saved.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Darter%3B227launch.jpg?width=1024"},{"name":"USS Flying Fish (SS-229)","rarity":"common","id":"uss-flying-fish-ss-229","subtitle":"Submarine","details":"Commissioned in 1941, Gato-class Flying Fish sighted the Japanese fleet approaching Midway in 1942 and went on to complete twelve war patrols.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Flying_Fish%3B0822902.jpg?width=1024"},{"name":"USS Finback (SS-230)","rarity":"common","id":"uss-finback-ss-230","subtitle":"Submarine","details":"Commissioned in 1942, Finback rescued downed naval aviator George H. W. Bush, the future president, after his bomber was shot down in 1944.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_FINBACK_%28SS-230%29.tif?width=1024"},{"name":"USS Haddo (SS-255)","rarity":"common","id":"uss-haddo-ss-255","subtitle":"Submarine","details":"Commissioned in 1942, Gato-class Haddo made nine war patrols and helped sink two Japanese destroyers in a single celebrated August 1944 action.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Haddo%3B0825502.jpg?width=1024"},{"name":"USS Hake (SS-256)","rarity":"common","id":"uss-hake-ss-256","subtitle":"Submarine","details":"Commissioned in 1942, Gato-class Hake made eleven war patrols and later served the Atlantic Fleet as a hunter-killer submarine after the war.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Hake%3B0825611.jpg?width=1024"},{"name":"USS Hoe (SS-258)","rarity":"common","id":"uss-hoe-ss-258","subtitle":"Submarine","details":"Commissioned in 1942, Gato-class Hoe made eight war patrols, sinking Japanese shipping from the South China Sea to the waters off Indochina.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Hoe%3B0825802.jpg?width=1024"},{"name":"USS Jack (SS-259)","rarity":"common","id":"uss-jack-ss-259","subtitle":"Submarine","details":"Commissioned in 1943, Gato-class Jack became famous for savaging Japanese oil convoys, sinking four tankers from one convoy in February 1944.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Jack%3B0825901.jpg?width=1024"},{"name":"USS Lapon (SS-260)","rarity":"common","id":"uss-lapon-ss-260","subtitle":"Submarine","details":"Commissioned in 1942, Gato-class Lapon made eight war patrols in the South China Sea and later served the Greek navy under the name Poseidon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Lapon%3B0826002.jpg?width=1024"},{"name":"USS Mingo (SS-261)","rarity":"common","id":"uss-mingo-ss-261","subtitle":"Submarine","details":"Commissioned in 1943, Gato-class Mingo made seven war patrols and later served Japan's Maritime Self-Defense Force under the name Kuroshio.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Mingo%3B0826106.jpg?width=1024"},{"name":"USS Muskallunge (SS-262)","rarity":"common","id":"uss-muskallunge-ss-262","subtitle":"Submarine","details":"Commissioned in 1943, Gato-class Muskallunge made seven war patrols and later served the Brazilian navy under the name Humaita for many years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Muskallunge%3B0826201.jpg?width=1024"},{"name":"USS Paddle (SS-263)","rarity":"common","id":"uss-paddle-ss-263","subtitle":"Submarine","details":"Commissioned in 1943, Gato-class Paddle made eight war patrols and later served the Brazilian navy under the name Goias until the year 1968.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Paddle%3B0826305.jpg?width=1024"},{"name":"USS Pargo (SS-264)","rarity":"common","id":"uss-pargo-ss-264","subtitle":"Submarine","details":"Commissioned in 1943, Gato-class Pargo made eight aggressive war patrols, earning a Navy Unit Commendation for her seventh patrol in 1945.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Pargo%3B0826401.jpg?width=1024"},{"name":"USS Tang (SS-563)","rarity":"common","id":"uss-tang-ss-563","subtitle":"Submarine","details":"Lead ship of the first postwar U.S. submarine class, commissioned in 1951, Tang carried wartime lessons into a faster, quieter diesel design.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Uss_Tang_0856301.jpg?width=1024"},{"name":"USS Darter (SS-576)","rarity":"common","id":"uss-darter-ss-576","subtitle":"Submarine","details":"Commissioned in 1956, Darter was a one-of-a-kind submarine built as an improved Tang-class design and spent her career in the Pacific Fleet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Darter_%28SS-576%29.jpg?width=1024"},{"name":"USS Barbel (SS-580)","rarity":"common","id":"uss-barbel-ss-580","subtitle":"Submarine","details":"Commissioned in 1959, Barbel led the last class of diesel-electric attack submarines built for the U.S. Navy, with an Albacore-style teardrop hull.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Barbel%3B0858005.jpg?width=1024"},{"name":"USS Tunny (SSG-282)","rarity":"common","id":"uss-tunny-ssg-282","subtitle":"Guided Missile Submarine","details":"Commissioned in 1942, Gato-class Tunny won nine battle stars, then carried Regulus missiles and later special-operations teams into the 1990s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Tunny_%28SS-282%29_0828229.jpg?width=1024"},{"name":"USS Raleigh (LPD-1)","rarity":"common","id":"uss-raleigh-lpd-1","subtitle":"Amphibious Transport Dock","details":"Lead ship of the first class built as amphibious transport docks, commissioned in 1962, Raleigh pioneered the floodable well deck and stern gate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Raleigh_%28LPD-1%29_underway_in_Guantanamo_Bay%2C_Cuba%2C_on_1_February_1963_%28NH_107694%29.jpg?width=1024"},{"name":"USS Green Bay (LPD-20)","rarity":"common","id":"uss-green-bay-lpd-20","subtitle":"Amphibious Transport Dock","details":"Commissioned in 2009, Green Bay is a San Antonio-class transport dock named for the Wisconsin city, ferrying Marines, hovercraft and Ospreys.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Green_Bay_%28LPD_20%29_near_New_Orleans.jpg?width=1024"},{"name":"USS Dixie (AD-14)","rarity":"common","id":"uss-dixie-ad-14","subtitle":"Destroyer Tender","details":"Commissioned in 1940, Dixie tended Pacific destroyers through World War II and long after, a San Diego harbor fixture for over four decades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Dixie_%28AD-14%29_underway_off_the_coast_of_southern_California_on_1_April_1976_%286392044%29.jpg?width=1024"},{"name":"USS Prairie (AD-15)","rarity":"common","id":"uss-prairie-ad-15","subtitle":"Destroyer Tender","details":"Commissioned in 1939 as a Dixie-class destroyer tender, Prairie repaired and resupplied destroyers across the Pacific during World War II.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Prairie_%28AD-15%29_at_anchor_in_the_1960s.jpg?width=1024"},{"name":"USS Samuel Gompers (AD-37)","rarity":"common","id":"uss-samuel-gompers-ad-37","subtitle":"Destroyer Tender","details":"Commissioned in 1967 and named for the labor leader, Samuel Gompers tended destroyers with full machine shops for nearly three decades at sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Samuel%20Gompers%20%28AD-37%29%20underway%20in%20the%20Pacific%20Ocean%20on%201%20August%201982%20%286349794%29.jpg?width=1024"},{"name":"USS Puget Sound (AD-38)","rarity":"common","id":"uss-puget-sound-ad-38","subtitle":"Destroyer Tender","details":"Commissioned in 1968, Puget Sound was a floating repair yard for destroyers, working from East Coast ports to the Mediterranean for decades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Puget_Sound_%28AD-38%29_underway%2C_in_1988_%286440885%29.jpg?width=1024"},{"name":"USS Yellowstone (AD-41)","rarity":"common","id":"uss-yellowstone-ad-41","subtitle":"Destroyer Tender","details":"Commissioned in 1980, Yellowstone was the last Samuel Gompers-class destroyer tender, a floating industrial plant for Atlantic Fleet warships.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Yellowstone_AD-41_1981.jpeg?width=1024"},{"name":"USS Fulton (AS-11)","rarity":"common","id":"uss-fulton-as-11","subtitle":"Submarine Tender","details":"Commissioned in 1941, Fulton tended Pacific submarines through World War II, refitting the boats between their long and dangerous war patrols.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Fulton_%28AS-11%29_at_Pearl_Harbor%2C_Oahu%2C_Hawaii_%28USA%29%2C_on_8_June_1942_%2880-G-10120%29.jpg?width=1024"},{"name":"USS Sperry (AS-12)","rarity":"common","id":"uss-sperry-as-12","subtitle":"Submarine Tender","details":"Commissioned in 1942, Sperry kept Pacific Fleet submarines fighting through World War II, then tended boats at San Diego for four more decades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Sperry%20%28AS-12%29%20underway%20off%20the%20Mare%20Island%20Naval%20Shipyard%2C%20California%20%28USA%29%2C%20on%2024%20July%201942%20%28NH%20107759%29.jpg?width=1024"},{"name":"USS Bushnell (AS-15)","rarity":"common","id":"uss-bushnell-as-15","subtitle":"Submarine Tender","details":"Commissioned in 1943, Bushnell tended submarines from Key West to the Pacific, supporting the silent service for more than a quarter century.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Bushnell_AS-15_1947.jpg?width=1024"},{"name":"USS Orion (AS-18)","rarity":"common","id":"uss-orion-as-18","subtitle":"Submarine Tender","details":"Commissioned in 1943, Orion spent half a century tending submarines, ending her career minding missile boats at La Maddalena, Italy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Orion_%28AS-18%29_anchored_at_Naval_Support_Activity_La_Maddalena%2C_Italy%2C_on_1_September_1983_%286369543%29.jpg?width=1024"},{"name":"USS Proteus (AS-19)","rarity":"common","id":"uss-proteus-as-19","subtitle":"Submarine Tender","details":"Commissioned in 1944 as a Fulton-class tender, Proteus was rebuilt to service Polaris missile submarines on their Cold War deterrent patrols.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Proteus_AS-19_1980.jpeg?width=1024"},{"name":"USS Hunley (AS-31)","rarity":"common","id":"uss-hunley-as-31","subtitle":"Submarine Tender","details":"The first tender designed for ballistic-missile submarines, commissioned in 1962, Hunley pioneered alongside missile handling at Holy Loch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Hunley%20%28AS-31%29%20off%20Agana%20Bay%2C%20Guam%2C%20on%201%20August%201980%20%286451565%29.jpg?width=1024"},{"name":"USS Holland (AS-32)","rarity":"common","id":"uss-holland-as-32","subtitle":"Submarine Tender","details":"Commissioned in 1963, Holland tended Polaris and Poseidon submarines from Holy Loch to Guam, her cranes swapping missiles between deterrent boats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Holland_%28AS-32%29.jpg?width=1024"},{"name":"USS Simon Lake (AS-33)","rarity":"common","id":"uss-simon-lake-as-33","subtitle":"Submarine Tender","details":"Commissioned in 1964, Simon Lake supported fleet ballistic-missile submarines at Holy Loch and Kings Bay through the Cold War deterrent years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Simon%20Lake%20%28AS-33%29%20Kings%20Bay%201981.jpeg?width=1024"},{"name":"USS Canopus (AS-34)","rarity":"common","id":"uss-canopus-as-34","subtitle":"Submarine Tender","details":"Commissioned in 1965, Canopus tended ballistic-missile submarines at Rota, Holy Loch and Kings Bay, a workhorse of the silent service ashore.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_Canopus.jpg?width=1024"},{"name":"USS Frank Cable (AS-40)","rarity":"common","id":"uss-frank-cable-as-40","subtitle":"Submarine Tender","details":"Named for an early submarine pioneer, Frank Cable is an Emory S. Land-class tender that has supported Pacific Fleet submarines from Guam.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Frank%20Cable%20%28AS-40%29%20departs%20Pearl%20Harbor%2C%20Hawaii%20%28USA%29%2C%20on%2025%20April%202005%20%28050425-N-8937A-018%29.jpg?width=1024"},{"name":"USS Emory S. Land (AS-39)","rarity":"common","id":"uss-emory-s-land-as-39","subtitle":"Submarine Tender","details":"Lead ship of her class, commissioned in 1979, Emory S. Land is a mobile repair and supply base keeping forward-deployed submarines on patrol.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US%20Navy%20100814-N-1401J-076%20USS%20Emory%20S.%20Land%20%28AS%2039%29%20arrives%20at%20her%20new%20homeport%20of%20Diego%20Garcia.jpg?width=1024"},{"name":"USS McKee (AS-41)","rarity":"common","id":"uss-mckee-as-41","subtitle":"Submarine Tender","details":"Commissioned in 1981, McKee was the third Emory S. Land-class tender, repairing West Coast submarines at San Diego until the end of the 1990s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS_McKee_%28AS-41%29_underway_at_sea%2C_circa_in_the_1980s.jpg?width=1024"},{"name":"USS Merrimack","rarity":"common","id":"uss-merrimack-1855","subtitle":"Steam Frigate","details":"Launched in 1855, the steam frigate Merrimack was burned at Norfolk in 1861; the Confederacy rebuilt her raised hull as the ironclad CSS Virginia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Merrimack%20-%20NH%2046248.jpg?width=1024"},{"name":"USS Powhatan","rarity":"common","id":"uss-powhatan-1850","subtitle":"Steam Frigate","details":"Launched in 1850, side-wheel frigate Powhatan carried Japan's first embassy toward Washington in 1860 and blockaded Southern ports in the Civil War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Powhatan%20%281850%29%20photograph%20NH%2048102.jpg?width=1024"},{"name":"USS Susquehanna","rarity":"common","id":"uss-susquehanna-1850","subtitle":"Steam Frigate","details":"Launched in 1850, Susquehanna was Commodore Perry's flagship for the 1853-54 expedition to Japan, and later fought for the Union in the Civil War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Susquehanna%20sidewheel%20steam%20frigate%20by%20Gutekunst%2C%201860s.jpg?width=1024"},{"name":"USS Niagara (1855)","rarity":"common","id":"uss-niagara-1855","subtitle":"Steam Frigate","details":"Launched in 1855, the great steam frigate Niagara laid the deep-sea stretch of the first transatlantic telegraph cable in the summer of 1858.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Niagara%20%281855%29.jpg?width=1024"},{"name":"USS Brooklyn","rarity":"common","id":"uss-brooklyn-1858","subtitle":"Steam Sloop","details":"Launched in 1858, the screw sloop Brooklyn fought at New Orleans in 1862 and steamed just ahead of Hartford into Mobile Bay in August 1864.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Brooklyn%201858.jpg?width=1024"},{"name":"USS Richmond","rarity":"common","id":"uss-richmond-1860","subtitle":"Steam Sloop","details":"Launched in 1860, the screw sloop Richmond blockaded Southern ports, ran the batteries at Port Hudson, and fought at Mobile Bay in 1864.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Steamer%20Richmond.jpg?width=1024"},{"name":"USS Iroquois","rarity":"common","id":"uss-iroquois-1859","subtitle":"Steam Sloop","details":"Launched in 1859, the screw sloop Iroquois fought at New Orleans and Vicksburg and cornered the Confederate raider Sumter at Martinique in 1862.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Iroquois1859.jpg?width=1024"},{"name":"USS Oneida","rarity":"common","id":"uss-oneida-1861","subtitle":"Steam Sloop","details":"Launched in 1861, the screw sloop Oneida fought at New Orleans and Mobile Bay; she sank off Yokohama in 1870 after a collision with a steamer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sinking%20of%20USS%20Oneida.jpg?width=1024"},{"name":"USS Princeton","rarity":"common","id":"uss-princeton-1843","subtitle":"Steam Sloop","details":"Launched in 1843, Princeton was the Navy's first propeller-driven warship; in 1844 a bursting cannon aboard killed two U.S. cabinet secretaries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Princeton%2C%20starboard%20side%2C%20underway%20-%20NARA%20-%20513006.jpg?width=1024"},{"name":"USS Michigan","rarity":"common","id":"uss-michigan-1843","subtitle":"Iron Steam Warship","details":"Launched in 1843, Michigan was the U.S. Navy's first iron-hulled warship; she patrolled the Great Lakes for decades and was renamed Wolverine in 1905.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/USS%20Wolverine%20%28IX-31%29%20001.jpg?width=1024"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
